//! Conversions between Rust values and [`Value`].

use acvm::{AcirField, FieldElement};
use anyhow::{anyhow, Result};

use super::Value;

/// Converts a Rust value into Noir's [`Value`] representation.
///
/// Implemented for `bool`, unsigned and signed integers, [`FieldElement`], `String`/`str`,
/// fixed-size arrays, tuples up to arity 12, and structs generated by `nrg!`. Signed integers are
/// encoded in two's complement at their bit width, matching the Noir ABI.
pub trait ToValue {
    /// Performs the conversion.
    fn to_value(&self) -> Value;
}

/// Converts Noir's [`Value`] back into a Rust value.
///
/// The counterpart of [`ToValue`].
pub trait FromValue: Sized {
    /// Performs the conversion.
    ///
    /// # Errors
    ///
    /// Fails if `value` has the wrong shape or does not fit in `Self`.
    fn from_value(value: Value) -> Result<Self>;
}

impl<T: ToValue + ?Sized> ToValue for &T {
    fn to_value(&self) -> Value {
        (**self).to_value()
    }
}

fn expect_field(value: Value, ty: &str) -> Result<FieldElement> {
    match value {
        Value::Field(field) => Ok(field),
        other => Err(anyhow!(
            "expected a field element for `{ty}`, got {other:?}"
        )),
    }
}

impl ToValue for bool {
    fn to_value(&self) -> Value {
        Value::Field(FieldElement::from(u128::from(*self)))
    }
}

impl FromValue for bool {
    fn from_value(value: Value) -> Result<Self> {
        let field = expect_field(value, "bool")?;
        if field.is_zero() {
            Ok(false)
        } else if field.is_one() {
            Ok(true)
        } else {
            Err(anyhow!("expected 0 or 1 for `bool`, got {field}"))
        }
    }
}

macro_rules! impl_unsigned {
    ($($ty:ty),+) => {$(
        impl ToValue for $ty {
            fn to_value(&self) -> Value {
                Value::Field(FieldElement::from(*self as u128))
            }
        }

        impl FromValue for $ty {
            fn from_value(value: Value) -> Result<Self> {
                let field = expect_field(value, stringify!($ty))?;
                field
                    .try_into_u128()
                    .and_then(|v| <$ty>::try_from(v).ok())
                    .ok_or_else(|| anyhow!("{field} does not fit into `{}`", stringify!($ty)))
            }
        }
    )+};
}

macro_rules! impl_signed {
    ($($ty:ty => $uty:ty),+) => {$(
        impl ToValue for $ty {
            fn to_value(&self) -> Value {
                // Two's complement at the type's own width, as the Noir ABI expects.
                Value::Field(FieldElement::from(*self as $uty as u128))
            }
        }

        impl FromValue for $ty {
            fn from_value(value: Value) -> Result<Self> {
                let field = expect_field(value, stringify!($ty))?;
                field
                    .try_into_u128()
                    .and_then(|v| <$uty>::try_from(v).ok())
                    .map(|raw| raw as $ty)
                    .ok_or_else(|| anyhow!("{field} does not fit into `{}`", stringify!($ty)))
            }
        }
    )+};
}

impl_unsigned!(u8, u16, u32, u64, u128, usize);
impl_signed!(i8 => u8, i16 => u16, i32 => u32, i64 => u64, i128 => u128, isize => usize);

impl ToValue for FieldElement {
    fn to_value(&self) -> Value {
        Value::Field(*self)
    }
}

impl FromValue for FieldElement {
    fn from_value(value: Value) -> Result<Self> {
        expect_field(value, "Field")
    }
}

impl ToValue for str {
    fn to_value(&self) -> Value {
        Value::String(self.to_owned())
    }
}

impl ToValue for String {
    fn to_value(&self) -> Value {
        Value::String(self.clone())
    }
}

impl FromValue for String {
    fn from_value(value: Value) -> Result<Self> {
        match value {
            Value::String(s) => Ok(s),
            // Return values are decoded as raw bytes; reassemble them.
            Value::Array(bytes) => {
                let bytes = bytes
                    .into_iter()
                    .map(u8::from_value)
                    .collect::<Result<Vec<_>>>()?;
                // Noir strings may hold arbitrary bytes; decode lossily, as nargo does.
                Ok(String::from_utf8_lossy(&bytes).into_owned())
            }
            other => Err(anyhow!("expected a string, got {other:?}")),
        }
    }
}

impl<T: ToValue, const N: usize> ToValue for [T; N] {
    fn to_value(&self) -> Value {
        Value::Array(self.iter().map(ToValue::to_value).collect())
    }
}

impl<T: FromValue, const N: usize> FromValue for [T; N] {
    fn from_value(value: Value) -> Result<Self> {
        let Value::Array(values) = value else {
            return Err(anyhow!("expected an array of length {N}, got {value:?}"));
        };
        if values.len() != N {
            return Err(anyhow!(
                "expected an array of length {N}, got {}",
                values.len()
            ));
        }
        let items = values
            .into_iter()
            .map(T::from_value)
            .collect::<Result<Vec<_>>>()?;
        // Length was checked above, so this cannot fail.
        items
            .try_into()
            .map_err(|_| anyhow!("array length mismatch"))
    }
}

macro_rules! impl_tuple {
    ($len:literal: $($name:ident),+) => {
        #[allow(non_snake_case)]
        impl<$($name: ToValue),+> ToValue for ($($name,)+) {
            fn to_value(&self) -> Value {
                let ($($name,)+) = self;
                Value::Array(vec![$($name.to_value()),+])
            }
        }

        #[allow(non_snake_case)]
        impl<$($name: FromValue),+> FromValue for ($($name,)+) {
            fn from_value(value: Value) -> Result<Self> {
                let Value::Array(values) = value else {
                    return Err(anyhow!("expected a tuple of length {}, got {value:?}", $len));
                };
                let [$($name),+]: [Value; $len] = values.try_into().map_err(|v: Vec<_>| {
                    anyhow!("expected a tuple of length {}, got {}", $len, v.len())
                })?;
                Ok(($($name::from_value($name)?,)+))
            }
        }
    };
}

impl_tuple!(1: A);
impl_tuple!(2: A, B);
impl_tuple!(3: A, B, C);
impl_tuple!(4: A, B, C, D);
impl_tuple!(5: A, B, C, D, E);
impl_tuple!(6: A, B, C, D, E, F);
impl_tuple!(7: A, B, C, D, E, F, G);
impl_tuple!(8: A, B, C, D, E, F, G, H);
impl_tuple!(9: A, B, C, D, E, F, G, H, I);
impl_tuple!(10: A, B, C, D, E, F, G, H, I, J);
impl_tuple!(11: A, B, C, D, E, F, G, H, I, J, K);
impl_tuple!(12: A, B, C, D, E, F, G, H, I, J, K, L);

impl ToValue for () {
    fn to_value(&self) -> Value {
        Value::Array(Vec::new())
    }
}

impl FromValue for () {
    fn from_value(_: Value) -> Result<Self> {
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use std::fmt;

    use super::*;

    fn round_trip<T>(value: T)
    where
        T: ToValue + FromValue + PartialEq + fmt::Debug,
    {
        assert_eq!(T::from_value(value.to_value()).unwrap(), value);
    }

    #[test]
    fn scalars_round_trip() {
        round_trip(true);
        round_trip(u8::MAX);
        round_trip(u128::MAX);
        round_trip(-1i8);
        round_trip(i64::MIN);
        round_trip(FieldElement::from(42u128));
        round_trip(String::from("noir"));
    }

    #[test]
    fn signed_uses_twos_complement_at_width() {
        let Value::Field(f) = (-1i32).to_value() else {
            unreachable!()
        };
        assert_eq!(f.try_into_u128(), Some(u128::from(u32::MAX)));
    }

    #[test]
    fn aggregates_round_trip() {
        round_trip([1u16, 2, 3]);
        round_trip((7u32, false));
        round_trip((1u8, (2u16, [true, false]), -3i32));
        round_trip((
            1u8, 2u8, 3u8, 4u8, 5u8, 6u8, 7u8, 8u8, 9u8, 10u8, 11u8, 12u8,
        ));
    }

    #[test]
    fn shape_errors_are_reported() {
        let err = <[u8; 2]>::from_value([1u8, 2, 3].to_value()).unwrap_err();
        assert!(err.to_string().contains("length 2"), "{err}");
        let err = u8::from_value(300u32.to_value()).unwrap_err();
        assert!(err.to_string().contains("u8"), "{err}");
    }
}
